const html = `<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Cadastro Manual · Desafoga TDAH</title>
  <link href="https://fonts.googleapis.com/css2?family=Sora:wght@300;400;500;600;700&family=DM+Mono:wght@400;500&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --bg: #0e0e11; --surface: #17171c; --border: #2a2a35;
      --accent: #7c5cfc; --accent-light: #a68fff; --text: #f0eeff;
      --muted: #7a7890; --success: #3ecf8e; --danger: #ff5e6c; --input-bg: #1e1e27;
    }
    body {
      font-family: 'Sora', sans-serif; background: var(--bg); color: var(--text);
      min-height: 100vh; display: flex; align-items: center; justify-content: center;
      padding: 2rem 1rem; position: relative; overflow-x: hidden;
    }
    body::before {
      content: ''; position: fixed; top: -200px; left: 50%; transform: translateX(-50%);
      width: 700px; height: 500px;
      background: radial-gradient(ellipse at center, rgba(124,92,252,0.18) 0%, transparent 70%);
      pointer-events: none; z-index: 0;
    }
    .card {
      position: relative; z-index: 1; background: var(--surface);
      border: 1px solid var(--border); border-radius: 20px;
      padding: 2.5rem 2.5rem 2rem; width: 100%; max-width: 500px;
      box-shadow: 0 0 60px rgba(124,92,252,0.08), 0 24px 64px rgba(0,0,0,0.5);
    }
    .logo-area { display: flex; align-items: center; gap: 0.7rem; margin-bottom: 1.8rem; }
    .logo-icon {
      width: 36px; height: 36px; background: var(--accent); border-radius: 10px;
      display: flex; align-items: center; justify-content: center; font-size: 1rem;
    }
    .logo-text { font-size: 0.95rem; font-weight: 600; color: var(--text); letter-spacing: -0.01em; }
    .logo-sub {
      font-size: 0.7rem; font-weight: 400; color: var(--muted);
      font-family: 'DM Mono', monospace; letter-spacing: 0.05em; text-transform: uppercase;
    }
    h1 { font-size: 1.45rem; font-weight: 700; letter-spacing: -0.03em; margin-bottom: 0.4rem; }
    .subtitle { font-size: 0.82rem; color: var(--muted); margin-bottom: 2rem; }
    .divider { height: 1px; background: var(--border); margin-bottom: 1.8rem; }
    .form-grid { display: flex; flex-direction: column; gap: 1.2rem; }
    .form-row { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
    .field { display: flex; flex-direction: column; gap: 0.45rem; }
    label {
      font-size: 0.76rem; font-weight: 500; color: var(--muted);
      font-family: 'DM Mono', monospace; text-transform: uppercase; letter-spacing: 0.06em;
    }
    input, select {
      background: var(--input-bg); border: 1px solid var(--border); border-radius: 10px;
      color: var(--text); font-family: 'Sora', sans-serif; font-size: 0.9rem;
      padding: 0.72rem 1rem; outline: none; transition: border-color 0.2s, box-shadow 0.2s;
      width: 100%; appearance: none; -webkit-appearance: none;
    }
    input[type="date"]::-webkit-calendar-picker-indicator { filter: invert(0.6); cursor: pointer; }
    input::placeholder { color: var(--muted); opacity: 0.6; }
    input:focus, select:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(124,92,252,0.18); }
    input.error { border-color: var(--danger); box-shadow: 0 0 0 3px rgba(255,94,108,0.18); }
    .field-hint { font-size: 0.72rem; color: var(--muted); font-family: 'DM Mono', monospace; }
    .select-wrapper { position: relative; }
    .select-wrapper::after {
      content: '▾'; position: absolute; right: 1rem; top: 50%; transform: translateY(-50%);
      color: var(--muted); pointer-events: none; font-size: 0.85rem;
    }
    .toggle-group { display: flex; gap: 0.6rem; }
    .toggle-option { flex: 1; position: relative; }
    .toggle-option input[type="radio"] { position: absolute; opacity: 0; width: 0; height: 0; }
    .toggle-option label {
      display: flex; align-items: center; justify-content: center; gap: 0.4rem;
      padding: 0.72rem 1rem; border-radius: 10px; border: 1px solid var(--border);
      background: var(--input-bg); cursor: pointer; font-family: 'Sora', sans-serif;
      font-size: 0.88rem; font-weight: 500; text-transform: none; letter-spacing: 0;
      color: var(--muted); transition: all 0.2s;
    }
    .toggle-option input[type="radio"]:checked + label {
      border-color: var(--accent); background: rgba(124,92,252,0.12);
      color: var(--accent-light); box-shadow: 0 0 0 3px rgba(124,92,252,0.15);
    }
    .toggle-option label:hover { border-color: rgba(124,92,252,0.4); color: var(--text); }
    .dot { width: 8px; height: 8px; border-radius: 50%; background: currentColor; display: inline-block; }
    .field-validade {
      overflow: hidden; max-height: 0; opacity: 0;
      transition: max-height 0.3s ease, opacity 0.3s ease;
    }
    .field-validade.visivel { max-height: 80px; opacity: 1; }
    .btn {
      margin-top: 0.5rem; width: 100%; padding: 0.9rem; border-radius: 12px; border: none;
      background: var(--accent); color: #fff; font-family: 'Sora', sans-serif;
      font-size: 0.95rem; font-weight: 600; cursor: pointer; letter-spacing: -0.01em;
      transition: background 0.2s, transform 0.15s, box-shadow 0.2s;
      display: flex; align-items: center; justify-content: center; gap: 0.5rem;
    }
    .btn:hover { background: var(--accent-light); box-shadow: 0 4px 24px rgba(124,92,252,0.35); }
    .btn:active { transform: scale(0.98); }
    .btn:disabled { opacity: 0.6; cursor: not-allowed; transform: none; }
    .spinner {
      width: 16px; height: 16px; border: 2px solid rgba(255,255,255,0.4);
      border-top-color: #fff; border-radius: 50%; animation: spin 0.7s linear infinite; display: none;
    }
    @keyframes spin { to { transform: rotate(360deg); } }
    .toast {
      position: fixed; bottom: 2rem; left: 50%;
      transform: translateX(-50%) translateY(20px); padding: 0.9rem 1.5rem;
      border-radius: 12px; font-size: 0.88rem; font-weight: 500; opacity: 0;
      transition: all 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
      pointer-events: none; z-index: 999; white-space: nowrap;
    }
    .toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
    .toast.success { background: rgba(62,207,142,0.15); border: 1px solid var(--success); color: var(--success); }
    .toast.error { background: rgba(255,94,108,0.15); border: 1px solid var(--danger); color: var(--danger); }
  </style>
</head>
<body>
  <div class="card">
    <div class="logo-area">
      <div class="logo-icon">🧠</div>
      <div>
        <div class="logo-text">Desafoga TDAH</div>
        <div class="logo-sub">Admin · Cadastro Manual</div>
      </div>
    </div>
    <h1>Novo usuário</h1>
    <p class="subtitle">Preencha os dados para ativar o acesso manualmente.</p>
    <div class="divider"></div>
    <div class="form-grid">

      <div class="field">
        <label for="nome">Nome completo</label>
        <input type="text" id="nome" placeholder="Ex: Maria Silva" autocomplete="off" />
      </div>

      <div class="form-row">
        <div class="field">
          <label for="genero">Gênero</label>
          <div class="select-wrapper">
            <select id="genero">
              <option value="" disabled selected>Selecionar</option>
              <option value="feminino">Feminino</option>
              <option value="masculino">Masculino</option>
            </select>
          </div>
        </div>
        <div class="field">
          <label for="email">E-mail</label>
          <input type="email" id="email" placeholder="email@exemplo.com" />
        </div>
      </div>

      <div class="field">
        <label>API</label>
        <div class="toggle-group">
          <div class="toggle-option">
            <input type="radio" id="api_oficial" name="api" value="oficial" checked />
            <label for="api_oficial"><span class="dot"></span> API Oficial</label>
          </div>
          <div class="toggle-option">
            <input type="radio" id="api_uazapi" name="api" value="uazapi" />
            <label for="api_uazapi"><span class="dot"></span> UAZAPI</label>
          </div>
        </div>
      </div>

      <div class="field">
        <label>Número WhatsApp</label>
        <div class="toggle-group">
          <div class="toggle-option">
            <input type="radio" id="pais_br" name="pais" value="brasil" checked onchange="atualizarCampTelefone()" />
            <label for="pais_br">🇧🇷 Brasil</label>
          </div>
          <div class="toggle-option">
            <input type="radio" id="pais_ext" name="pais" value="estrangeiro" onchange="atualizarCampTelefone()" />
            <label for="pais_ext">🌍 Estrangeiro</label>
          </div>
        </div>
      </div>

      <div class="field">
        <label for="telefone">WhatsApp</label>
        <input type="tel" id="telefone" placeholder="5511999999999" maxlength="13" inputmode="numeric" />
        <span class="field-hint" id="telefone-hint">55 + DDD (2 dígitos) + número (9 dígitos) · total: 13 dígitos</span>
      </div>

      <div class="field">
        <label>Plano</label>
        <div class="toggle-group">
          <div class="toggle-option">
            <input type="radio" id="ativo" name="plano" value="ativo" checked onchange="atualizarValidade()" />
            <label for="ativo"><span class="dot"></span> Ativo</label>
          </div>
          <div class="toggle-option">
            <input type="radio" id="inativo" name="plano" value="inativo" onchange="atualizarValidade()" />
            <label for="inativo"><span class="dot"></span> Inativo</label>
          </div>
          <div class="toggle-option">
            <input type="radio" id="vitalicio" name="plano" value="" onchange="atualizarValidade()" />
            <label for="vitalicio"><span class="dot"></span> Vitalício</label>
          </div>
        </div>
      </div>

      <div class="field-validade visivel" id="wrapValidade">
        <div class="field">
          <label for="validade">Válido até</label>
          <input type="date" id="validade" />
          <span class="field-hint">Data de expiração do acesso ativo</span>
        </div>
      </div>

      <button class="btn" id="btnEnviar" onclick="enviarFormulario()">
        <span class="spinner" id="spinner"></span>
        <span id="btnTexto">Enviar cadastro</span>
      </button>

    </div>
  </div>
  <div class="toast" id="toast"></div>
  <script>
    function atualizarValidade() {
      const isAtivo = document.getElementById('ativo').checked;
      const wrap    = document.getElementById('wrapValidade');
      if (isAtivo) {
        wrap.classList.add('visivel');
      } else {
        wrap.classList.remove('visivel');
        document.getElementById('validade').value = '';
      }
    }

    function atualizarCampTelefone() {
      const isBrasil = document.getElementById('pais_br').checked;
      const input = document.getElementById('telefone');
      const hint  = document.getElementById('telefone-hint');
      if (isBrasil) {
        input.placeholder = '5511999999999';
        input.maxLength   = 13;
        hint.textContent  = '55 + DDD (2 dígitos) + número (9 dígitos) · total: 13 dígitos';
      } else {
        input.placeholder = 'Ex: 14155552671';
        input.maxLength   = 20;
        hint.textContent  = 'Código do país + DDD + número, sem espaços ou símbolos';
      }
      input.value = '';
      input.classList.remove('error');
    }

    function validarTelefoneBrasil(tel) {
      const digits = tel.replace(/\\D/g, '');
      if (digits.length !== 13) return false;
      if (!digits.startsWith('55')) return false;
      if (digits[4] !== '9') return false;
      return true;
    }

    function getOntem() {
      const d = new Date();
      d.setDate(d.getDate() - 1);
      return d.toISOString().split('T')[0];
    }

    function mostrarToast(msg, tipo) {
      const t = document.getElementById('toast');
      t.textContent = msg;
      t.className = 'toast ' + tipo;
      t.classList.add('show');
      setTimeout(() => t.classList.remove('show'), 3500);
    }

    async function enviarFormulario() {
      const nome     = document.getElementById('nome').value.trim();
      const genero   = document.getElementById('genero').value;
      const email    = document.getElementById('email').value.trim();
      const telefone = document.getElementById('telefone').value.trim();
      const plano    = document.querySelector('input[name="plano"]:checked').value;
      const api      = document.querySelector('input[name="api"]:checked').value;
      const pais     = document.querySelector('input[name="pais"]:checked').value;
      const validade = document.getElementById('validade').value;

      if (!nome || !genero || !email || !telefone) {
        mostrarToast('⚠️ Preencha todos os campos.', 'error');
        return;
      }

      if (plano === 'ativo' && !validade) {
        mostrarToast('⚠️ Informe a data de validade do plano ativo.', 'error');
        document.getElementById('validade').focus();
        return;
      }

      if (pais === 'brasil' && !validarTelefoneBrasil(telefone)) {
        document.getElementById('telefone').classList.add('error');
        mostrarToast('⚠️ Número BR deve ter 13 dígitos: 55 + DDD + 9 dígitos.', 'error');
        return;
      }
      document.getElementById('telefone').classList.remove('error');

      let validadeFinal = null;
      if (plano === 'ativo')   validadeFinal = validade;
      if (plano === 'inativo') validadeFinal = getOntem();

      const btn     = document.getElementById('btnEnviar');
      const spinner = document.getElementById('spinner');
      const texto   = document.getElementById('btnTexto');
      btn.disabled          = true;
      spinner.style.display = 'block';
      texto.textContent     = 'Enviando…';

      try {
        const res = await fetch('https://primary-production-cc15d.up.railway.app/webhook/pagamento-manual', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ nome, genero, email, telefone, plano, api, pais, validade: validadeFinal })
        });
        if (res.ok) {
          mostrarToast('✅ Cadastro enviado com sucesso!', 'success');
          document.getElementById('nome').value          = '';
          document.getElementById('genero').value        = '';
          document.getElementById('email').value         = '';
          document.getElementById('telefone').value      = '';
          document.getElementById('validade').value      = '';
          document.getElementById('ativo').checked       = true;
          document.getElementById('api_oficial').checked = true;
          document.getElementById('pais_br').checked     = true;
          atualizarCampTelefone();
          atualizarValidade();
        } else {
          mostrarToast('❌ Erro ao enviar. Tente novamente.', 'error');
        }
      } catch (e) {
        mostrarToast('❌ Falha de conexão. Verifique a rede.', 'error');
      } finally {
        btn.disabled          = false;
        spinner.style.display = 'none';
        texto.textContent     = 'Enviar cadastro';
      }
    }
  </script>
</body>
</html>`;

return [{ json: { html } }];
